/* addAccommodationInfo */
INSERT INTO ACCOMMODATION_INFO (
    REGN_ID
    , CONTENT_ID
    , ACCOM_NM
    , ACCOM_TYPE
    , ADDR1
    , ADDR2
    , MAPX
    , MAPY
    , TEL
    , THUMBNAIL
    , lclsSystm1
    , lclsSystm2
    , lclsSystm3
)
VALUES (
    #{regnId}
    , #{contentId}
    , #{accomNm}
    , #{accomType}
    , #{addr1}
    , #{addr2}
    , #{mapx}
    , #{mapy}
    , #{tel}
    , #{thumbnail}
    , #{lclsSystm1}
    , #{lclsSystm2}
    , #{lclsSystm3}
)
ON DUPLICATE KEY UPDATE
    REGN_ID = #{regnId}
    , ACCOM_NM = #{accomNm}
    , ACCOM_TYPE = #{accomType}
    , ADDR1 = #{addr1}
    , ADDR2 = #{addr2}
    , MAPX = #{mapx}
    , MAPY = #{mapy}
    , TEL = #{tel}
    , THUMBNAIL = #{thumbnail}
    , lclsSystm1 = #{lclsSystm1}
    , lclsSystm2 = #{lclsSystm2}
    , lclsSystm3 = #{lclsSystm3}
    , updated_at = CURRENT_TIMESTAMP
